class Solution:
    def maxConsistentColumns(self, grid: List[List[int]], limit: int) -> int:
        from functools import lru_cache
        m, n = len(grid), len(grid[0])

        @lru_cache(maxsize=None)
        def solve(last):
            best = 1
            for j in range(last + 1, n):
                ok = True
                if last >= 0:
                    for i in range(m):
                        if abs(grid[i][j] - grid[i][last]) > limit:
                            ok = False
                            break
                if ok:
                    best = max(best, 1 + solve(j))
            return best

        return solve(-1) - 1

